// SPDX-License-Identifier: MIT
pragma solidity ^0.8.34;

contract Greeting {
    string private greeting;
    address public owner;

    string private constant DEFAULT_GREETING = "Hello, World!";

    event GreetingChanged(address changer, string newGreeting);

    constructor(string memory _g) {
        owner = msg.sender;
        greeting = _g;
        emit GreetingChanged(msg.sender, _g);
    }

    function setGreeting(string memory _g) public {
        require(msg.sender == owner, "Greeting: caller is not the owner");
        greeting = _g;
        emit GreetingChanged(msg.sender, _g);
    }

    function greet() public view returns (string memory) {
        return greeting;
    }

    function resetGreeting() public {
        require(msg.sender == owner, "Greeting: caller is not the owner");
        greeting = DEFAULT_GREETING;
        emit GreetingChanged(msg.sender, DEFAULT_GREETING);
    }
}

contracts/01_Storage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.34;

contract Storage {
    uint256 private storedData;

    event ValueSet(address indexed who, uint256 newValue);

    constructor(uint256 _init) {
        storedData = _init;
        emit ValueSet(msg.sender, _init);
    }

    function set(uint256 _value) public {
        storedData = _value;
        emit ValueSet(msg.sender, _value);
    }

    function get() public view returns (uint256) {
        return storedData;
    }
}

contracts/03_Counter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.34;

contract Counter {
    uint256 public count;
    uint256 public constant MAX = 100;

    event Incremented(address indexed who, uint256 newCount);
    event Decremented(address indexed who, uint256 newCount);
    event Reset(address indexed who);

    function increment() public {
        require(count < MAX, "Max limit reached");
        count += 1;
        emit Incremented(msg.sender, count);
    }

    function decrement() public {
        require(count > 0, "Count is zero");
        count -= 1;
        emit Decremented(msg.sender, count);
    }

    function reset() public {
        count = 0;
        emit Reset(msg.sender);
    }
}

contracts/04_Ownable.sol.content:
 // SPDX-License-Identifier: MIT
pragma solidity ^0.8.34;

// Parent Contract
contract Ownable {
    address public owner;

    event OwnershipTransferred(
        address indexed previousOwner,
        address indexed newOwner
    );

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not the owner");
        _;
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Invalid owner address");

        address previousOwner = owner;
        owner = newOwner;

        emit OwnershipTransferred(previousOwner, newOwner);
    }
}

// Child Contract
contract ProtectedVault is Ownable {
    uint256 private treasure;

    event Deposited(address indexed sender, uint256 amount);
    event Withdrawn(address indexed to, uint256 amount);

    // Anyone can deposit ETH
    function deposit() public payable {
        treasure += msg.value;
        emit Deposited(msg.sender, msg.value);
    }

    // Only owner can withdraw ETH
    function withdraw(address to, uint256 amt) public onlyOwner {
        require(to != address(0), "Invalid recipient");
        require(amt <= address(this).balance, "Insufficient balance");

        require(amt <= treasure, "Insufficient treasure");

        treasure -= amt;

        (bool success, ) = payable(to).call{value: amt}("");
        require(success, "ETH transfer failed");

        emit Withdrawn(to, amt);
    }

    // Return the actual ETH balance of the contract
    function contractBalance() public view returns (uint256) {
        return address(this).balance;
    }
}
